@Composable
fun PlayerSurface(
    channel: Channel?,
    muted: Boolean = false,
    captionsEnabled: Boolean = false
) {
    when (channel?.source) {
        ChannelSource.HLS,
        ChannelSource.IPTV -> StreamSurface(channel, muted, captionsEnabled)
        else -> IdleSurface()
    }
}

@Composable
private fun StreamSurface(
    channel: Channel,
    muted: Boolean,
    captionsEnabled: Boolean
) {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    val health = remember(context) { StreamHealthRepository(context.applicationContext) }
    val candidates = remember(channel.id, channel.uri, channel.backupUris) {
        health.order(channel.playbackUris())
    }

    var candidateIndex by remember(channel.id, candidates) { mutableIntStateOf(0) }
    var retryAttempt by remember(channel.id) { mutableIntStateOf(0) }
    var retryGeneration by remember(channel.id) { mutableIntStateOf(0) }

    if (candidates.isEmpty()) {
        IdleSurface()
        return
    }

    val player = remember {
        val loadControl = DefaultLoadControl.Builder()
            .setBufferDurationsMs(1_500, 12_000, 350, 750)
            .build()

        val renderersFactory = DefaultRenderersFactory(context)
            .setEnableDecoderFallback(true)

        ExoPlayer.Builder(context, renderersFactory)
            .setLoadControl(loadControl)
            .build()
            .apply {
                playWhenReady = true
                setHandleAudioBecomingNoisy(true)
                trackSelectionParameters = trackSelectionParameters
                    .buildUpon()
                    .setPreferredAudioLanguage("pt")
                    .setPreferredTextLanguage("pt-BR")
                    .setTrackTypeDisabled(C.TRACK_TYPE_TEXT, true)
                    .build()
            }
    }

    LaunchedEffect(muted) {
        player.volume = if (muted) 0f else 1f
    }

    LaunchedEffect(captionsEnabled) {
        player.trackSelectionParameters = player.trackSelectionParameters
            .buildUpon()
            .setPreferredTextLanguage("pt-BR")
            .setTrackTypeDisabled(C.TRACK_TYPE_TEXT, !captionsEnabled)
            .build()
    }

    val safeIndex = candidateIndex.coerceIn(0, candidates.lastIndex)
    val uri = candidates[safeIndex]

    DisposableEffect(player, uri, candidates.size, retryGeneration) {
        var bufferingJob: Job? = null
        var recoveryScheduled = false

        fun recover() {
            if (recoveryScheduled) return
            recoveryScheduled = true
            health.markFailure(uri)

            val next = PlaybackPolicy.nextIndex(candidateIndex, candidates.size)
            if (next != null) {
                candidateIndex = next
                retryAttempt = 0
            } else {
                val attempt = retryAttempt
                scope.launch {
                    delay(PlaybackPolicy.retryDelayMillis(attempt))
                    retryAttempt = (attempt + 1).coerceAtMost(6)
                    candidateIndex = 0
                    retryGeneration += 1
                }
            }
        }

        val listener = object : Player.Listener {
            override fun onPlayerError(error: PlaybackException) {
                bufferingJob?.cancel()
                bufferingJob = null
                recover()
            }

            override fun onPlaybackStateChanged(playbackState: Int) {
                when (playbackState) {
                    Player.STATE_READY -> {
                        bufferingJob?.cancel()
                        bufferingJob = null
                        recoveryScheduled = false
                        retryAttempt = 0
                        health.markSuccess(uri)
                    }

                    Player.STATE_BUFFERING -> {
                        bufferingJob?.cancel()
                        bufferingJob = scope.launch {
                            delay(BUFFERING_FAILOVER_MS)
                            if (player.playbackState == Player.STATE_BUFFERING) recover()
                        }
                    }

                    else -> Unit
                }
            }
        }

        player.addListener(listener)
        onDispose {
            bufferingJob?.cancel()
            player.removeListener(listener)
        }
    }

    LaunchedEffect(channel.id, uri, retryGeneration) {
        val lower = uri.lowercase()
        val item = MediaItem.Builder()
            .setUri(uri)
            .apply {
                when {
                    ".m3u8" in lower -> setMimeType(MimeTypes.APPLICATION_M3U8)
                    ".mpd" in lower -> setMimeType(MimeTypes.APPLICATION_MPD)
                }
            }
            .build()

        player.stop()
        player.clearMediaItems()
        player.setMediaItem(item)
        player.prepare()
        player.play()
    }

    DisposableEffect(player) {
        onDispose { player.release() }
    }

    AndroidView(
        factory = {
            PlayerView(it).apply {
                useController = false
                resizeMode = AspectRatioFrameLayout.RESIZE_MODE_FIT
                setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING)
                this.player = player
            }
        },
        update = { it.player = player },
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black)
    )
}

@Composable
private fun IdleSurface() {
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(
                Brush.radialGradient(
                    colors = listOf(Color(0xFF12212C), SanchesColors.Background),
                    radius = 1500f
                )
            )
    )
}

private const val BUFFERING_FAILOVER_MS = 8_000L

