    val base = remember(
        state.channels,
        state.favorites,
        state.recentChannelIds,
        state.mostWatchedIds,
        section
    ) {
        when (section) {
            "Favoritos" -> state.channels.filter { it.id in state.favorites }
            "Recentes" -> channelsByIds(state.channels, state.recentChannelIds)
            "Mais assistidos" -> channelsByIds(state.channels, state.mostWatchedIds)
            "A-Z", "Todos" -> state.channels.sortedBy { ChannelResolver.normalize(it.name) }
            else -> state.channels
                .filter { ChannelClassifier.category(it) == section }
                .sortedBy { ChannelResolver.normalize(it.name) }
        }
    }

    val filtered = remember(base, query, letter) {
        val q = ChannelResolver.normalize(query)
        base.filter { channel ->
            val queryMatch = q.isBlank() ||
                ChannelResolver.normalize(channel.name).contains(q) ||
                ChannelResolver.normalize(channel.category).contains(q)
            val first = ChannelResolver.normalize(channel.name)
                .firstOrNull()
                ?.uppercaseChar()
                ?.toString()
            queryMatch && (letter == null || first == letter)
        }
    }

    val focused = filtered.firstOrNull { it.id == focusedId }
        ?: state.channels.firstOrNull { it.id == focusedId }
        ?: filtered.firstOrNull()

    LaunchedEffect(focused?.id) {
        previewChannel = null
        if (focused != null) {
            delay(600)
            previewChannel = focused
        }
    }

    Row(
        modifier = Modifier
            .fillMaxSize()
            .padding(20.dp),
        horizontalArrangement = Arrangement.spacedBy(13.dp)
    ) {
        CategoryPanel(
            sections = sections,
            selected = section,
            onSelected = { selected ->
                section = selected
                query = ""
                letter = null
                controller.rememberNavigator(selected, null)
            }
        )

        Column(
            modifier = Modifier
                .weight(1f)
                .fillMaxHeight()
        ) {
            Text(
                section,
                color = SanchesColors.PrimaryText,
                fontSize = 27.sp,
                fontWeight = FontWeight.Black
            )
            Text(
                filtered.size.toString() + " canais • segure ↑/↓ para rolar",
                color = SanchesColors.SecondaryText,
                fontSize = 12.sp
            )

            Spacer(Modifier.height(8.dp))

            OutlinedTextField(
                value = query,
                onValueChange = { query = it },
                singleLine = true,
                label = { Text("Filtrar por nome") },
                modifier = Modifier.fillMaxWidth()
            )

            Spacer(Modifier.height(7.dp))

            LazyRow(horizontalArrangement = Arrangement.spacedBy(5.dp)) {
                item {
                    NavigatorChip("Todos", letter == null) { letter = null }
                }
                items(('A'..'Z').map(Char::toString)) { item ->
                    NavigatorChip(item, letter == item) { letter = item }
                }
            }

            Spacer(Modifier.height(8.dp))

            LazyColumn(
                modifier = Modifier.fillMaxSize(),
                verticalArrangement = Arrangement.spacedBy(6.dp)
            ) {
                items(filtered, key = { it.id }) { channel ->
                    NavigatorChannelItem(
                        channel = channel,
                        program = state.programs[channel.id],
                        favorite = channel.id in state.favorites,
                        selected = channel.id == state.currentChannel?.id,
                        onFocused = {
                            focusedId = channel.id
                            controller.rememberNavigator(section, channel.id)
                        },
                        onWatch = { controller.select(channel) },
                        onFavorite = { controller.toggleFavorite(channel) }
                    )
                }
            }
        }

        NavigatorPreview(
            channel = focused,
            previewChannel = previewChannel,
            program = focused?.let { state.programs[it.id] },
            favorite = focused?.id in state.favorites,
            onWatch = { focused?.let(controller::select) },
            onFavorite = { focused?.let(controller::toggleFavorite) }
        )
    }
}

