package com.mukasanches.zapptv.playback

object PlaybackPolicy {
    fun order(
        candidates: List<String>,
        scoreOf: (String) -> Int
    ): List<String> =
        candidates
            .map(String::trim)
            .filter { it.startsWith("http://", true) || it.startsWith("https://", true) }
            .distinct()
            .sortedWith(
                compareByDescending<String> { scoreOf(it) }
                    .thenByDescending { it.startsWith("https://", true) }
            )

    fun nextIndex(currentIndex: Int, size: Int): Int? =
        (currentIndex + 1).takeIf { size > 0 && it < size }

    fun retryDelayMillis(attempt: Int): Long {
        val safeAttempt = attempt.coerceIn(0, 5)
        return (600L shl safeAttempt).coerceAtMost(12_000L)
    }
}

package com.mukasanches.zapptv.playback

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

class PlaybackPolicyTest {
    @Test
    fun ordersByHealthThenHttps() {
        val scores = mapOf(
            "http://a.test/live.m3u8" to 2,
            "https://b.test/live.m3u8" to 2,
            "https://c.test/live.m3u8" to 8
        )

        val ordered = PlaybackPolicy.order(scores.keys.toList()) { scores[it] ?: 0 }

        assertEquals("https://c.test/live.m3u8", ordered[0])
        assertEquals("https://b.test/live.m3u8", ordered[1])
        assertEquals("http://a.test/live.m3u8", ordered[2])
    }

    @Test
    fun advancesOnlyInsideCandidateList() {
        assertEquals(1, PlaybackPolicy.nextIndex(0, 2))
        assertNull(PlaybackPolicy.nextIndex(1, 2))
    }

    @Test
    fun retryBackoffIsBounded() {
        assertEquals(600L, PlaybackPolicy.retryDelayMillis(0))
        assertEquals(1200L, PlaybackPolicy.retryDelayMillis(1))
        assertEquals(12000L, PlaybackPolicy.retryDelayMillis(10))
    }
}
